#[path="../canonical-root/root.rs"]mod root;
#[path="../batched/inverse.rs"]mod inverse;
use hec_native_ic::{counted,fp::Fp,jac::{Curve,Div},poly::Poly,instance::factor_base,rng::Rng};
#[derive(Clone,Debug,PartialEq,Eq)]struct Report{row:Option<(usize,u64,u64,u64,u64,u64)>,anchors:usize,trials:usize}
fn prefix(c:&Curve,core:(u64,u64),d:&Div,target:&Div,sm:u64)->Report{assert!(c.is_valid(d)&&c.is_valid(target));assert!(!c.is_zero(d));let base=c.place(core.0,core.1);assert!(c.is_valid(&base));assert_eq!(c.mul(&base,sm),*d);let f=&c.fp;let z=root::power_map(f,5).0;let mut ratios=vec![];let mut den=vec![];let mut q=1;for _ in 1..5{q=f.mul(q,z);let sum=f.add(1,q);den.push(sum);ratios.push((q,f.mul(sum,sum)));}let iv=inverse::invert(&den,f);let mut source=vec![];let mut x=core.0;for _ in 0..5{source.push((x,core.1));x=f.mul(x,z);}let mut anchor=*target;let mut trials=0;for ai in 1..=16{anchor=c.add_place(&anchor,core.0,core.1);if anchor.u.deg()!=2{continue}let mut entries=vec![];let mut denominators=vec![];for &(x,y)in &source{let u=anchor.u.eval(x,f);if u!=0{entries.push((x,y,anchor.v.eval(x,f)));denominators.push(u);}}let inverses=inverse::invert(&denominators,f);for(&(x,y,v),inv)in entries.iter().zip(inverses){for yy in[y,f.neg(y)]{trials+=1;let t=f.mul(f.sub(yy,v),inv);let tt=f.mul(t,t);let h1=f.neg(f.add(tt,anchor.u.c[1]));let w1=f.add(anchor.v.c[1],f.mul(t,anchor.u.c[1]));let h2=f.neg(f.add(f.add(f.mul(f.mul(2,t),w1),f.mul(anchor.u.c[1],h1)),anchor.u.c[0]));let s=f.sub(f.add(tt,anchor.u.c[1]),x);let pp=f.sub(h2,f.mul(x,s));if s==0{continue}let ss=f.mul(s,s);for(i,&(q,den2))in ratios.iter().enumerate(){if f.mul(pp,den2)==f.mul(q,ss){let x2=f.mul(s,iv[i]);let x3=f.mul(q,x2);return Report{row:Some((ai,t,x,yy,x2,x3)),anchors:ai,trials}}}}}}Report{row:None,anchors:16,trials}}
fn main(){counted::disable();let(mut cells,mut found)=(0,0);println!("p\tsm\tcase\trep\tfound\tanchors\ttrials\tmodulus\tcounts");for(p,cc,ell)in[(101,2,7481),(251,18,67931),(601,7,411491)]{let c=Curve::new(Fp::new(p),Poly::from_coeffs(&[cc,0,0,0,0,1]));let fb=factor_base(&c);let core=fb[0];let base=c.place(core.0,core.1);let mut rng=Rng::new(2026113000^p);for sm in[1,17]{let d=c.mul(&base,sm);for case in 0..2{let k=1+rng.below(ell-1);let target=c.mul(&d,k);let mut first=None;for rep in 0..2{counted::reset();let report=prefix(&c,core,&d,&target,sm);let counts=counted::snapshot();counted::disable();if let Some((ai,t,x,y,x2,x3))=report.row{let mut anchor=target;for _ in 0..ai{anchor=c.add(&anchor,&base);}let w=anchor.v.add(&anchor.u.scale(t,&c.fp),&c.fp);assert_eq!(w.eval(x,&c.fp),y);let h=c.f.sub(&w.mul(&w,&c.fp),&c.fp).div_exact(&anchor.u,&c.fp);let roots=Poly::x_minus(x,&c.fp).mul(&Poly::x_minus(x2,&c.fp),&c.fp).mul(&Poly::x_minus(x3,&c.fp),&c.fp);assert_eq!(h,roots);let sum=c.add_place(&c.add_place(&c.add_place(&anchor,x,y),x2,w.eval(x2,&c.fp)),x3,w.eval(x3,&c.fp));assert!(c.is_zero(&sum));}let signature=(report.clone(),counts.clone());if let Some(ref old)=first{assert_eq!(old,&signature)}else{first=Some(signature)}for(m,v)in &counts{assert_eq!(v[8],2*v[7]+v[5]+v[6]);println!("{p}\t{sm}\t{case}\t{rep}\t{}\t{}\t{}\t{m}\t{}",report.row.is_some(),report.anchors,report.trials,v.iter().map(u64::to_string).collect::<Vec<_>>().join(","));}if rep==0{found+=usize::from(report.row.is_some());println!("REPORT\tp={p}\tsm={sm}\tcase={case}\t{report:?}");}}cells+=1;}}}assert_eq!(cells,12);assert_eq!(found,10);eprintln!("PASS original_cells={cells} first_grounding_cells={found} no_trigger_cells={} exact_principal_native_group=true repeat_vectors_exact=true prefix_only_no_solver_claim=true independent_verification=false",cells-found);}
